var rotarci = function(a) {
  const n = a.length;
  const m = a[0].length;
  for(let i=0;i<n;i++) {
    let aux =a[i][0] ;
    for(let j=0;j<m-1 ; j++) a[i][j] =a[i][j+1] ;
    a[i][m-1] = aux;
  }
  return a;
};

var rotarci_a = function(a) {
  const m = a[0].length-1;
  let aux, k;
  for(const f of a) {
    aux =f[0] ; k =0 ;
    for(const _ of f) f[k] = k===m? aux : f[++k];
  }
  return a;
};

var rotarci_b = function(a) {
  const m = a[0].length-1;
  let aux;
  a.forEach(f=>{
    aux = f[0];
    f.forEach((_,k)=>f[k] =k===m ? aux : f[k+1]);
  });
  return a;
};

var interCols = function(a,k,l) {
  const n = a.length;
  const m = a[0].length;
  if (k<0 || k>=m) throw "1ra columna inválida";
  if (l<0 || l>=m) throw "2da columna inválida";
  for(let i=0; i<n; i++) {
    let aux=a[i][k];
    a[i][k]=a[i][l];
    a[i][l]=aux;
  }
  return a;
};

var interCols_a = function(a,k,l) {
