var swapCols = function(a) {
  const n = a.length;
  const m = a[0].length;
  for(let i=0; i<n; i++) 
    for(let k=0, l=m-1; l>=m/2; k++, l--) {
      let aux=a[i][k];
      a[i][k]=a[i][l];
      a[i][l]=aux;
    }
  return a;
};

var swapCols_a = function(a) {
  const m = a[0].length-1;
  let aux, l;
  a.every( f=> {
    l=m;
    f.every((_,k) => {
      if (l>k) {
        aux=f[k];
        f[k]=f[l];
        f[l]=aux;
        l--;
        return true;
      }
    });
    return true;
  });
  return a;
};

var swapCols_b = function(a) {
    const m = a[0].length-1;
    let aux, k, l;
    for(const f of a) {
      k=0; l=m;
      for(const _ of f) {
        if(l>k) {
          aux=f[k];
          f[k]=f[l];
          f[l]=aux;
          l--;
          k++;
        } else break;
      }
    }
    return a;
  };

var  unshiftCol = function(a,v) {
  const n = a.length;
  const m = v.length;
  if (n!=m) throw "vector incompatible";
  for(let i=0; i<n; i++) a[i].unshift(v[i]);
  return a;
};

var unshiftCol_a = function(a,v) {
  const n = a.length;
  const m = v.length;
  if (n!=m) throw "vector incompatible";
  a.forEach((f,i)=>f.unshift(v[i]));
  return a;
};

var popCol = function(a) {
  const n = a.length;
  v = []
  for (let i=0; i<n; i++) v.push(a[i].pop());
  return v;
};

var popCol_a = function(a){
  const n = a.length;
  v = [];
  a.every(f=>(v.push(f.pop()),true));
  return v;
}

var transpuesta = function(a) {
  const n = a.length;
  const m = a[0].length;
  const b = [];
  for (let j=0; j<m; j++) {
    b.push([]);
    for (let i=0; i<n; i++) {
      b[j].push(a[i][j]);
    }
  }
  return b;
};

var transpuesta_b = function(a) {
  const b = [];
  a[0].forEach((_,j)=>(b.push([]), a.forEach(fa=>b[j].push(fa[j]))));
  return b;
};

var mrAleatoria = function(n,m) {
  const a = [];
  for(let i=0; i<n;i++ ) {
    a.push([]);
    for (let j=0; j<m;j++ ) {
      a[i].push((Math.random()*8+1).round());
    }
  }
  return a;
};

var prodMat = function(a) {
  const n = a.length;
  const m = a[0].length;
  let p =1 ;
  for (let i=0; i<n;i++ ) 
    for (let j=0; j<m;j++)  p *= a[i][j];
  return p;
};

var prodMat_b = function(a) {
  let p =1 ;
  a.forEach(f=>f.forEach(e=>p*=e));
  return p;
};

var mulMat_g = function(a,b) {
  b = b.transpose();
  if (a[0].length!==b[0].length) throw "matrices incompatibles";
  return a.map(fa=>{
    let fc = [];
    for (const fb of b) fc.push(fa.reduce((s,_,k)=>s+fa[k]*fb[k], 0));
    return fc;
  });
};
